NAME = 'Est: Estonian Bible'
BOOK = 'Colossians'

CHAPTERS = {
    1: {
        1: 'Paulus, Jumala tahtel Jeesuse Kristuse Apostel, ja vend Timoteos,',
        2: 'Kolossas elavaile pühadele ja usklikele vendadele Kristuses. Armu teile ja rahu Jumalalt, meie Isalt, ja Issandalt Jeesuselt Kristuselt!',
        3: 'Me täname Jumalat ja oma Issanda Jeesuse Kristuse Isa, palvetades igal ajal teie eest,',
        4: 'sest me oleme kuulnud teie usust Kristuses Jeesuses ja teie armastusest kõigi pühade vastu,',
        5: 'mis teil on taevasse tallele pandud lootuse pärast, millest te varemalt olete kuulnud Evangeeliumi tõesõna kaudu,',
        6: 'mis on tulnud teie juurde ja nõnda kogu maailmas on kandmas vilja ning kasvab, nõnda ka teie seas alates sellest päevast, mil te kuulsite ja tunnetasite Jumala armu tõe sees,',
        7: 'nõnda nagu te seda ka õppisite Epafrase, meie armsa kaassulase käest, kes on ustav Kristuse abiline teie heaks,',
        8: 'kes meile ka on teatanud teie armastusest Vaimus.',
        9: 'Sellepärast ei ole ka meie sellest päevast, mil me seda kuulsime, lakanud palvet tegemast ja palumast teie eest, et teid täidetaks tema tahtmise tunnetusega kõiges vaimulikus tarkuses ja arusaamises,',
        10: 'et te elaksite väärikalt Issandale, et Temale kõigiti meeldida, vilja kandes kõiges heas töös ning kasvades Jumala tunnetuses',
        11: 'ja saades vägevaks kõige väega Tema au vägevust mööda kõigeks püsivuseks ja pikaks meeleks, rõõmuga',
        12: 'tänades Isa, Kes teid on teinud kõlbavaks osa saama püha rahva pärandist valguses,',
        13: 'Kes meid on päästnud pimeduse võimusest ja on meid asetanud Oma armsa Poja Riiki.',
        14: 'Temas on meil lunastus, pattude andekssaamine.',
        15: 'Tema on nähtamatu Jumala kuju, kõige loodu esmasündinu.',
        16: 'Sest Tema läbi on loodud kõik, mis on taevastes ja mis on maa peal, mis nähtav ja nähtamatu, olgu aujärjed, ülemused, valitsused, võimud; kõik on loodud Tema läbi ja Temasse;',
        17: 'ja Tema Ise on enne kõiki, ja kõik püsivad koos Tema sees;',
        18: 'ja Tema on ihu - see on Koguduse - pea; Ta on algus ja esmasündinu surnutest, et Ta kõiges saaks esikohale.',
        19: 'Sest Jumal arvas heaks kõik täiuse lasta elada Temas',
        20: 'ja tehes rahu ristivere läbi, lepitada Tema läbi Enese poole kõik, niihästi selle, mis on maa peal, kui ka selle, mis on taevas.',
        21: 'Ja Ta on teid, kes enne olite Temast võõrdunud ja oma meelsuse poolest vaenlased, tehes kurja, nüüd ka lepitatud oma lihalikus ihus surma läbi,',
        22: 'et seada teid pühadena ja veatuina ja laitmatuina enese ette,',
        23: 'kui te aga jääte ususse hästi rajatuina ja kindlaina ega lase endid ära pöörata Evangeeliumi lootusest, mida te olete kuulnud ja mis on kuulutatud kõigele loodule taeva all ja mille teenijaks mina, Paulus, olen saanud.',
        24: 'Nüüd ma olen rõõmus oma kannatamistes teie pärast, ja mis mul veel puudub Kristuse viletsustest, selle ma täiendan omas lihas Tema Ihu heaks, mis on Kogudus,',
        25: 'kelle teenijaks ma olen saanud Jumala korralduse järgi, mis minu kätte on usaldatud, et teile täielikult kuulutada Jumala sõna:',
        26: 'seda saladust, mis oli varjul endiste ajastute ja sugupõlvede eest, aga nüüd on avalikuks tehtud Tema pühadele,',
        27: 'kellele Jumal tahtis teada anda, milline on selle saladuse auhiilguse rikkus paganate seas - see on Kristus teie sees, auhiilguse lootus,',
        28: 'Keda me kuulutame, manitsedes igat inimest ja õpetades igat inimest kõiges tarkuses, et valmistada igat inimest täielikuks Kristuses.',
        29: 'Selle jaoks minagi näen vaeva ja võitlen Tema tarmu mööda, mis minus on vägevasti tegev.',
    },
    2: {
        1: 'Sellepärast ma tahan, et teil oleks teada, kui suur võitlus mul on teie ja laodikealaste pärast ja kõikide pärast, kes mu palet lihas ei ole näinud,',
        2: 'et saaksid kinnitust nende südamed, olles kokku liidetud armastuses ja täieliku mõistmise kogu rikkusesse ning tunnetaksid Jumala saladuse, Kristuse,',
        3: 'Kelles peituvad kõik tarkuse ja tunnetuse aarded.',
        4: 'Seda ma ütlen selleks, et keegi teid ei petaks meelitavate kõnedega.',
        5: 'Sest kuigi mina liha poolest olen eemal, olen ma siiski vaimus teiega ühes ning olen rõõmus, nähes teie head korda ja teie kindlat usku Kristusesse.',
        6: 'Otsekui te nüüd olete vastu võtnud Kristuse Jeesuse, Issanda, nõnda käige Temas',
        7: 'juurdunuina Temasse ja rajatuina Temale ning kinnitatuina usus, nõnda nagu teid on õpetatud, ja olge ülevoolavad tänus.',
        8: 'Vaadake, et keegi teid ei võtaks saagiks mõtteteaduse ja tühja pettusega, mis vastavad inimeste pärimusele, maailma algjõududele ja mitte Kristusele.',
        9: 'Sest Temas elab kõik Jumala olemise täius ihulikult.',
        10: 'Ja te olete täidetud Temas, Kes on iga valitsuse ja võimu pea;',
        11: 'ja Temas te olete ka ümber lõigatud ümberlõikamisega, mida ei toimetata kätega, vaid lihaliku ihu äraheitmise teel, Kristuse ümberlõikamisega,',
        12: 'kui teid ühes Temaga maha maeti ristimises, milles teid ühes üles äratati usu läbi, mis on tegev Jumala väes, Kes Tema surnuist üles äratas.',
        13: 'Ka teid, kes olite surnud üleastumistes ja oma ümberlõikamata lihas, on Ta ühes Temaga teinud elavaks, andes meile andeks kõik üleastumised,',
        14: 'kui Ta kustutas meie kohta käiva võlakirja ühes selle sätetega; see oli meie vastu ja selle Ta kõrvaldas, seda risti külge naelutades.',
        15: 'Ta riisus ülemustelt ja võimudelt relvad ning tegi nad avaliku pilke alusteks, võidutsedes nende üle Kristuses.',
        16: 'Sellepärast ärgu ükski mõistku kohut teie üle sööma või jooma ja pühade või noorkuu või hingamispäevade pärast,',
        17: 'mis on vaid tulevaste asjade vari, kuna ihu on Kristuse oma.',
        18: 'Ärgu siis teie võiduandi teilt riisugu ükski, kellele meeldib alandlikkus ja Inglite austamine ning kes tungib sellesse, mis ta nägemuses on näinud, lastes ilmaasjata ennast täis puhuda oma lihaliku meele poolt,',
        19: 'ja kes ei pea kinni peast, kelles kogu ihu kokku liidetakse ja koos hoitakse kõõluste ja sidemete abil ning kasvab Jumala poolt seatud kasvamist.',
        20: 'Kui te nüüd ühes Kristusega olete surnud maailma algjõududele, miks te siis, nagu elaksite maailmas, lasete endile teha määrusi:',
        21: '"Ära puuduta! Ära maitse! Ära katsu käega!"',
        22: '- seda, mis kõik on määratud kadumisele kulutamise teel - inimeste käskude ja õpetuste järgi?',
        23: 'Sel kõigel on küll tarkuse nägu omatehtud jumalateenistuse, alandlikkuse ja ihu kurnamise tõttu, aga mis on ilma erilise väärtuseta ja mis sünnib liha rahuldamiseks.',
    },
    3: {
        1: 'Kui te nüüd ühes Kristusega olete surnuist üles tõusnud, siis otsige seda, mis on ülal, kus Kristus on istumas Jumala paremal käel.',
        2: 'Mõelge sellele, mis on ülal, mitte sellele, mis on maa peal!',
        3: 'Sest teie olete surnud ja teie elu on varjul ühes Kristusega Jumalas.',
        4: 'Kui Kristus, meie elu, saab avalikuks, siis saate ka teie ühes Temaga avalikuks au sees.',
        5: 'Sellepärast surmake oma maapealsed liikmed: hoorus, roppus, kired, pahad himud ja ahnus, mis on ebajumalateenistus;',
        6: 'nende pärast tuleb Jumala viha;',
        7: 'nende sees käisite muiste ka teie, kui elasite neis.',
        8: 'Ent nüüd jätke teiegi maha see kõik: viha, ärritatavus, kurjus, pilkamine, ropud sõnad oma suust.',
        9: 'Ärge rääkige valet üksteisest, sest te olete endid lahti riietanud vanast inimesest tema tegudega,',
        10: 'ja olete riietunud uude inimesse, kes on uuendatud õigesti tunnetama oma Looja kuju järgi,',
        11: 'kus ei ole kreeklast ega juuti, ei ümberlõigatut ega ümberlõikamatut, ei harimatut ega sküüti, ei orja ega vaba, vaid kõik ja kõikide sees on Kristus!',
        12: 'Riietuge siis kui Jumala valitud pühad ja armastatud südamliku halastusega, heldusega, alandusega, tasadusega, pika meelega,',
        13: 'sallides üksteist ja andeks andes üksteisele, kui kellelgi on kaebust teise peale. Nõnda nagu Kristus teile on andeks andnud, nõnda tehke ka teie.',
        14: 'Aga kõigele sellele lisaks olgu armastus; see on täiuslik side.',
        15: 'Ja Kristuse rahu valitsegu teie südameis, sest selleks te olete kutsutud ühes ihus. Ja olge tänulikud.',
        16: 'Kristuse sõna elagu rohkesti teie seas. Kõige tarkusega õpetage ja juhatage üksteist psalmidega ja kiituslauludega ja vaimulike lauludega, tänumeeles lauldes Issandale oma südames.',
        17: 'Ja kõik, mida te iganes teete sõnaga või tööga, seda tehke kõik Issanda Jeesuse nimel, tänades Jumalat Isa Tema läbi.',
        18: 'Naised, olge meestele allaheitlikud, nõnda nagu on kohus Issandas.',
        19: 'Mehed, armastage oma naisi ja ärge olge karmid nende vastu.',
        20: 'Lapsed, olge oma vanemaile sõnakuulelikud kõigis asjus, sest see on Issandale meelepärast.',
        21: 'Isad, ärge ärritage oma lapsi, et nad ei läheks araks.',
        22: 'Orjad, olge sõnakuulelikud kõigis asjus neile, kes isandad on liha poolest, mitte silmakirjaks nagu need, kes püüavad olla inimestele meelepärast, vaid siirast südamest, kartes Issandat.',
        23: 'Mida te iganes teete, seda tehke südamest, nõnda nagu Issandale ja mitte nagu inimestele,',
        24: 'teades, et te saate Issandalt pärandi palga. Te teenite Issandat Kristust.',
        25: 'Aga kes teeb ülekohut, saab kätte, mis ta on ülekohut teinud, ja ei tehta vahet isikute vahel.',
    },
    4: {
        1: 'Isandad, tehke oma orjadele, mis on õige ja kohus, ja teadke, et ka teil on Issand taevas.',
        2: 'Jääge kindlasti palvesse ja valvake palves tänuga,',
        3: 'paludes ühtlasi ka meie eest, et Jumal meile avaks sõna ukse, et saaksime rääkida Kristuse saladust, mille pärast mina olengi seotud,',
        4: 'et ma seda võiksin avaldada, nõnda nagu mul tuleb kõnelda.',
        5: 'Kohelge targasti neid, kes on väljaspool, ja pidage aega kalliks.',
        6: 'Teie kõne olgu alati armu sees, soolaga soolatud, et te teaksite, kuidas teil tuleb igaühele kosta.',
        7: 'Kuidas mu käsi käib, küll seda kõike teatab teile Tühhikos, armas vend ja ustav abiline ning kaassulane Issandas,',
        8: 'kelle ma praegu läkitan teie juurde selle tarvis, et te saaksite teada, kuidas meie käsi käib, ja et ta kinnitaks teie südameid,',
        9: 'ühes ustava ja armsa venna Oneesimosega, kes on teie seast. Küll nad annavad teile teada, kuidas siin kõigega lugu on.',
        10: 'Teile saadab tervisi Aristarhos, mu vangiseltsiline, ja Markus, Barnabase õepoeg, kelle kohta te juba olete saanud juhatusi, et kui ta tuleb teie juurde, te võtaksite ta vastu.',
        11: 'Ja teid tervitab Jeesus, keda hüütakse Justuseks. Need on ümberlõigatuist olnud ainsad kaastöölised Jumala Riigi alal, ja nad on olnud mulle troostiks.',
        12: 'Teid tervitab Epafras, kes on teie seast, Kristuse Jeesuse sulane, kes alati võitleb teie eest palveis, et te püsiksite täiuslikena ja oleksite täidetud kõige Jumala tahtmisega.',
        13: 'Sest ma annan temale selle tunnistuse, et ta kannab väga suurt hoolt teie eest ja nende eest, kes on Laodikeas ja kes on Hierapolises.',
        14: 'Teid tervitab arst Luukas, kes mulle on armas, ja Deemas.',
        15: 'Tervitage vendi Laodikeas ja Nümfat ja kogudust ta majas.',
        16: 'Ja kui see kiri on loetud teie juures, siis tehke nii, et seda loetaks ka Laodikea Koguduses, ja et teie loeksite ka Laodikeast tulevat kirja.',
        17: 'Ja öelge Arhipposele: "Pea silmas oma ametit, mille sa oled saanud Issandalt, et sa seda täidaksid!"',
        18: 'See tervitus on minu, Pauluse, oma käega. Mõelge mu ahelatele! Arm teiega!',
    },
}
